const items = await $input.all();

// Определяем sevenDaysAgo
const sevenDaysAgo = new Date();
sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

// Функция для парсинга даты в формате DD.MM.YYYY HH:mm:ss
function parseCustomDate(dateStr) {
  const [datePart, timePart] = dateStr.split(' ');
  const [day, month, year] = datePart.split('.');
  const [hours, minutes, seconds] = timePart.split(':');

  // Месяцы в JS начинаются с 0 (январь = 0, февраль = 1 и т.д.)
  return new Date(year, month - 1, day, hours, minutes, seconds);
}

// Отладочные логи
console.log("sevenDaysAgo:", sevenDaysAgo); // Проверяем, как вычисляется sevenDaysAgo
console.log("Current Date:", new Date()); // Проверяем текущую дату

