const result = items
  .filter(item => {
    let rowDate;
    try {
      // Попытка парсинга даты
      rowDate = parseCustomDate(item.json['Время']);
      console.log("Original Date String:", item.json['Время']); // Проверяем исходную строку даты
      console.log("Parsed Date:", rowDate); // Проверяем, как парсится каждая дата
    } catch (error) {
      console.error(`Ошибка при парсинге даты: ${item.json['Время']}`);
      return false; // Если дата некорректна, пропускаем строку
    }
    console.log("Comparing dates:", rowDate >= sevenDaysAgo && rowDate <= new Date());
    return !isNaN(rowDate) && rowDate >= sevenDaysAgo && rowDate <= new Date();
  })
  .map(item => ({
    Транскрипция: item.json['Транскрипция'],
