  }));

return result;

const items = await $input.all();

// Формируем общий отчёт в HTML
let htmlReport = `
<!DOCTYPE html>
<html>
<head>
  <title>Отчёт по обращениям клиентов</title>
  <style>
    body {
      font-family: Arial, sans-serif;
      margin: 20px;
    }
    h1, h2 {
      color: #333;
    }
    ul {
      list-style-type: none;
      padding: 0;
      margin: 0;
    }
    li {
      margin-bottom: 10px;
    }
    strong {
      color: #007BFF;
    }
    .highlight {
      color: red;
    }
  </style>
</head>
<body>
  <h1>Отчёт по обращениям клиентов за неделю</h1>
`;

for (const item of items) {
  const content = item.json.message?.content;

  if (!content) {
    continue;
  }

  // Преобразуем текст в HTML
  let formattedContent = content.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>'); // Жирный шрифт
  formattedContent = formattedContent.replace(/\n\n+/g, '</p><p>'); // Разделяем абзацы
  formattedContent = formattedContent.replace(/\n/g, '<br>'); // Переносы строк

  htmlReport += `
  <div style="margin-bottom: 20px;">
    <h2>Запись</h2>
    <p>${formattedContent}</p>
  </div>
  `;
}

htmlReport += `
</body>
</html>
`;

return [{ json: { htmlReport } }];
